import { useId, type ChangeEvent, type FormEvent, type KeyboardEvent } from "react";
import "./CommandBox.css";

export interface CommandReply {
  text: string;
  isError?: boolean;
}

export interface CommandBoxProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (value: string) => void;
  placeholder?: string;
  reply?: CommandReply;
}

export function CommandBox({
  value,
  onChange,
  onSubmit,
  placeholder = "Type a command, e.g. “log stretch 10m”",
  reply,
}: CommandBoxProps) {
  const replyId = useId();
  const inputId = useId();

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    onChange(event.target.value);
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = value.trim();
    if (trimmed.length === 0) {
      return;
    }
    onSubmit(trimmed);
  };

  // Escape clears a non-empty input; with an empty input it is left alone
  // so it can still be handled by the surrounding dashboard.
  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Escape" && value.length > 0) {
      event.preventDefault();
      onChange("");
    }
  };

  const hasReply = reply !== undefined && reply.text.length > 0;
  const replyClassName = [
    "command-box__reply",
    reply?.isError ? "command-box__reply--error" : "command-box__reply--normal",
  ].join(" ");

  return (
    <div className="command-box">
      <form className="command-box__form" role="search" onSubmit={handleSubmit}>
        <label className="command-box__label" htmlFor={inputId}>
          Command
        </label>
        <input
          id={inputId}
          className="command-box__input"
          type="text"
          autoComplete="off"
          autoCapitalize="off"
          spellCheck={false}
          placeholder={placeholder}
          value={value}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          aria-describedby={hasReply ? replyId : undefined}
          aria-invalid={reply?.isError ? true : undefined}
        />
      </form>
      {hasReply && (
        <div
          id={replyId}
          className={replyClassName}
          role={reply.isError ? "alert" : "status"}
          aria-live={reply.isError ? "assertive" : "polite"}
        >
          {reply.text}
        </div>
      )}
    </div>
  );
}
