}

.command-box__reply {
  box-sizing: border-box;
  padding: 0.55rem 0.8rem;
  font-size: 0.9rem;
  line-height: 1.45;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.command-box__reply--normal {
  color: var(--command-box-reply-text);
  background: var(--command-box-reply-bg);
  border-color: var(--command-box-border);
}

.command-box__reply--error {
  color: var(--command-box-error-text);
  background: var(--command-box-error-bg);
  border-color: var(--command-box-error-border);
}

@media (prefers-reduced-motion: reduce) {
  .command-box__input {
    transition: none;
  }
}
